impl ColorButton {
    pub const NONE: Option<&'static ColorButton> = None;

    /// Creates a new [`ColorButton`][crate::ColorButton] widget.
    ///
    /// This returns a button with a preview showing the color.
    /// When the button is clicked a GtkColorSelectionDialog is opened.
    /// If the user changes the color the new color is written into the
    /// array that was used to pass the initial color and the "color-changed"
    /// signal is emitted.
    /// ## `title`
    /// String that will be used as title for the color_selector.
    /// ## `width`
    /// Width of the colorpreview in pixels.
    /// ## `height`
    /// Height of the colorpreview in pixels.
    /// ## `color`
    /// A [`gegl::Color`][crate::gegl::Color].
    /// ## `type_`
    /// The type of transparency to be displayed.
    ///
    /// # Returns
    ///
    /// Pointer to the new [`ColorButton`][crate::ColorButton] widget.
    #[doc(alias = "gimp_color_button_new")]
    pub fn new(
        title: &str,
        width: i32,
        height: i32,
        color: &impl IsA<gegl::Color>,
        type_: ColorAreaType,
    ) -> ColorButton {
        unsafe {
            gtk::Widget::from_glib_none(ffi::gimp_color_button_new(
                title.to_glib_none().0,
                width,
                height,
                color.as_ref().to_glib_none().0,
                type_.into_glib(),
            ))
            .unsafe_cast()
        }
    }
}

